# Check vertex connectivity (minimum vertex cut size)
# For small graph we can brute force
import itertools
def vertex_connectivity(adj):
    n = len(adj)
    # For each subset of vertices, check if removal disconnects
    for k in range(0, n):  # size of cut
        for cut in itertools.combinations(range(n), k):
            # remove cut vertices
            remaining = [v for v in range(n) if v not in cut]
            if len(remaining) <= 1:
                return k  # can reduce to single vertex
            # check connectivity of remaining
            visited = set()
            stack = [remaining[0]]
            while stack:
                v = stack.pop()
                if v not in visited:
                    visited.add(v)
                    for u in adj[v]:
                        if u not in cut and u not in visited:
                            stack.append(u)
            if len(visited) != len(remaining):
                return k
    return n

print("Vertex connectivity:", vertex_connectivity(adj))

